#!/usr/bin/env node

/**
 * O86 Memory read-to-visible-Mapbox benchmark.
 *
 * Input geometry is captured from the isolated MySQL/API performance harness,
 * not generated by this script. Each trial starts a fresh browser context and
 * account so client geometry/module/storage caches are cold. Hosted Mapbox
 * tiles, the production Zustand stores, FogLayer and the actual Memory screen
 * remain in the measured path. Recorded healthy API p95 delays are injected
 * before the captured response to avoid reporting an impossible zero-network
 * fixture as end-to-end latency.
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { chromium } from 'playwright';

const fixturePath = process.env.CAIRN_O86_MEMORY_CLIENT_FIXTURE;
if (!fixturePath || !fs.existsSync(fixturePath)) {
  throw new Error('CAIRN_O86_MEMORY_CLIENT_FIXTURE must name the real isolated-API fixture');
}
const fixture = JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
const baseUrl = process.env.CAIRN_QA_URL || 'http://127.0.0.1:8081';
const outputDir = path.resolve(process.env.CAIRN_O86_MEMORY_MAPBOX_OUTPUT || '/tmp/cairn-o86-memory-mapbox-performance');
const trialCount = Number(process.env.CAIRN_O86_MEMORY_TRIALS || 20);
const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
fs.mkdirSync(outputDir, { recursive: true });

const sourceRows = fixture.sources?.sources ?? [];
const sourceById = new Map(sourceRows.map(source => [String(source.friend_id), source]));
const denseProjection = fixture.one_friend_dense_10k.projections[0];
const twoById = new Map(fixture.two_friends_dense_overlap_12k.projections
  .map(projection => [String(projection.source_friend_id), projection]));
const distinctProjection = fixture.one_friend_distinct_1k.projections[0];
const denseId = String(denseProjection.source_friend_id);
const overlapId = [...twoById.keys()].find(id => id !== denseId);
const distinctId = String(distinctProjection.source_friend_id);
if (!overlapId || !sourceById.has(denseId) || !sourceById.has(overlapId) || !sourceById.has(distinctId)) {
  throw new Error('fixture source identities are incomplete');
}

const allScenarios = [
  { id: 'mine-2k', scope: 'self', viewport: fixture.dense_viewport, selected: [], expectFriend: false, expectOverlap: false },
  { id: 'mine-plus-one-friend-10k', scope: 'combined', viewport: fixture.dense_viewport, selected: [denseId], expectFriend: true, expectOverlap: true },
  { id: 'mine-plus-two-friends-12k', scope: 'combined', viewport: fixture.dense_viewport, selected: [denseId, overlapId], expectFriend: true, expectOverlap: true },
  { id: 'friend-only-distinct-1k', scope: 'combined', viewport: fixture.distinct_viewport, selected: [distinctId], expectFriend: true, expectOverlap: false },
];
const requestedScenarios = new Set(String(process.env.CAIRN_O86_MEMORY_SCENARIOS || '')
  .split(',').map(value => value.trim()).filter(Boolean));
const scenarios = requestedScenarios.size
  ? allScenarios.filter(scenario => requestedScenarios.has(scenario.id))
  : allScenarios;

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const percentile = (values, fraction) => [...values].sort((a, b) => a - b)[Math.max(0, Math.ceil(values.length * fraction) - 1)] ?? 0;
const summarize = values => ({
  trials: values.length,
  p50_ms: Number(percentile(values, 0.5).toFixed(2)),
  p95_ms: Number(percentile(values, 0.95).toFixed(2)),
  max_ms: Number(Math.max(0, ...values).toFixed(2)),
  all_ms: values.map(value => Number(value.toFixed(2))),
});
const sha = value => crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex');
const freshAuthorization = body => {
  const authorized = new Date();
  const expires = new Date(authorized.getTime() + 24 * 60 * 60 * 1000);
  return {
    ...body,
    server_authorized_at: authorized.toISOString(),
    authorization_expires_at: expires.toISOString(),
    projections: (body.projections ?? []).map(projection => ({
      ...projection,
      server_authorized_at: authorized.toISOString(),
      authorization_expires_at: expires.toISOString(),
    })),
  };
};

const browser = await chromium.launch({
  headless: true,
  ...(fs.existsSync(chromePath) ? { executablePath: chromePath } : {}),
});
const results = [];
try {
  for (const scenario of scenarios) {
    const [west, south, east, north] = scenario.viewport;
    const center = { lng: (west + east) / 2, lat: (south + north) / 2 };
    // Keep the browser/network context so ordinary Mapbox resources can use
    // their normal HTTP cache. Each page below is a new JS realm and a unique
    // account with cleared storage, so application geometry caches stay cold.
    const context = await browser.newContext({
      viewport: { width: 390, height: 844 },
      deviceScaleFactor: 1,
      locale: 'en-NZ',
      colorScheme: 'light',
      geolocation: { latitude: center.lat, longitude: center.lng, accuracy: 8 },
      permissions: ['geolocation'],
    });
    try {
      for (let trial = 0; trial < trialCount; trial += 1) {
      const user = {
        id: `${fixture.viewer.id}-${scenario.id}-${trial}`,
        name: fixture.viewer.name,
        email: `o86-memory-${scenario.id}-${trial}@example.invalid`,
        createdAt: '2026-01-01T00:00:00.000Z',
        dateOfBirth: '1990-01-01', hasPassword: true, providers: ['email'],
      };
      const page = await context.newPage();
      const runtimeErrors = [];
      const clientLogs = [];
      page.on('pageerror', error => runtimeErrors.push(`pageerror:${error.message}`));
      page.on('console', message => {
        const value = message.text();
        if (message.type() === 'error' && !value.includes('Failed to load resource')) runtimeErrors.push(`console:${value}`);
      });
      await page.addInitScript(({ token, userId }) => {
        localStorage.clear();
        localStorage.setItem('cairn_jwt', token);
        localStorage.setItem('cairn_onboarding_v1_done', 'true');
        localStorage.setItem(`cairn_onboarding_v1_done_${userId}`, 'true');
        globalThis.__cairnMapQaLocalStyle = false;
        globalThis.__cairnMapQaTestMode = false;
      }, { token: `o86-memory-mapbox-${scenario.id}-${trial}`, userId: user.id });

      await page.route('**/api/**', async route => {
        const request = route.request();
        const url = new URL(request.url());
        const endpoint = url.pathname;
        const fulfill = async (body, delayMs = 0, status = 200) => {
          if (delayMs > 0) await sleep(delayMs);
          await route.fulfill({ status, contentType: 'application/json', body: JSON.stringify(body) });
        };
        if (endpoint === '/api/auth/me') return fulfill({ user });
        if (endpoint === '/api/edit-diag') {
          try {
            const payload = JSON.parse(request.postData() || '{}');
            clientLogs.push(...(payload.events ?? []).filter(event => String(event.tag ?? '').includes('fog') || String(event.tag ?? '').includes('mapbox')));
          } catch {}
          return fulfill({ ok: true });
        }
        if (endpoint === '/api/memory-subscriptions') {
          return fulfill({
            limit: null,
            count: scenario.selected.length,
            subscriptions: scenario.selected.map(id => ({
              friend_id: Number(id),
              friend_name: sourceById.get(id)?.friend_name ?? `Friend ${id}`,
              subscribed_at: '2026-10-18T00:00:00.000Z',
            })),
          }, 64);
        }
        if (endpoint === '/api/friend-sharing/sources') {
          return fulfill({
            sources: sourceRows.map(source => ({ ...source, selected: scenario.selected.includes(String(source.friend_id)) })),
          }, 64);
        }
        if (endpoint === '/api/memory/coverage') {
          if (scenario.id === 'friend-only-distinct-1k') {
            return fulfill({
              coverage_rule_version: 4,
              coverage_version: 'qa-empty-mine-distinct',
              evidence_count: 0, tile_count: 0, rebuilt_tile_count: 0,
              geometry: { type: 'MultiPolygon', coordinates: [] },
              stage_ms: {}, total_ms: 0,
            }, 140);
          }
          return fulfill(fixture.viewer_mine_2k, 140);
        }
        if (endpoint === '/api/memory/points' && request.method() === 'GET') {
          return fulfill({ points: [] });
        }
        if (endpoint === '/api/friend-sharing/coverage') {
          const requested = JSON.parse(request.postData() || '{}').friend_ids?.map(String) ?? [];
          const projections = requested.flatMap(id => {
            if (id === denseId) return [twoById.get(denseId) ?? denseProjection];
            if (id === overlapId) return [twoById.get(overlapId)];
            if (id === distinctId) return [distinctProjection];
            return [];
          }).filter(Boolean);
          return fulfill(freshAuthorization({
            coverage_rule_version: 4,
            total_ms: scenario.selected.length > 1 ? 255 : 224,
            projections,
            revoked_friend_ids: requested.filter(id => !projections.some(value => String(value.source_friend_id) === id)),
          }), scenario.selected.length > 1 ? 255 : 224);
        }
        if (endpoint === '/api/friends') return fulfill([]);
        if (endpoint === '/api/circle/markers') return fulfill({ markers: [] });
        if (endpoint.startsWith('/api/cairn-memory/')) return fulfill({ cairns: [], items: [], count: 0 });
        if (endpoint === '/api/sessions') return fulfill({ sessions: [] });
        if (endpoint === '/api/routes') return fulfill({ routes: [] });
        return fulfill({ data: [], markers: [], routes: [], sessions: [], notifications: [], count: 0 });
      });

      let measurement = null;
      try {
        await page.goto(baseUrl, { waitUntil: 'domcontentloaded', timeout: 120_000 });
        await page.waitForFunction(() => Boolean(globalThis.__cairnStores?.useMemoryStore && globalThis.__cairnStores?.navigationRef), null, { timeout: 120_000 });
        await page.waitForFunction(() => globalThis.__cairnStores.useAppStore.getState().hydrated === true, null, { timeout: 120_000 });
        await page.evaluate(({ userValue, centerValue, scopeValue }) => {
          const stores = globalThis.__cairnStores;
          stores.useSettingsStore.getState().saveAll({ debugMode: false, appearance: 'day', mapLayer: 'outdoors' });
          stores.useMemorySettingsStore.setState({ hydrated: true, firstVisitDone: true });
          stores.useMemoryScopeStore.setState({ ownerUserId: userValue.id, scope: scopeValue });
          stores.useMemorySubscriptionsStore.getState().reset();
          stores.useFriendMemoryStore.getState().reset();
          stores.useMemoryStore.setState(state => ({
            points: [], testPoints: [], pendingPreparedCoverageCids: [],
            geometryVersion: state.geometryVersion + 1,
            lastWatcherFix: { lat: centerValue.lat, lng: centerValue.lng, ts: Date.now() },
            initialRevealDone: true,
            localHydration: {
              ownerUserId: userValue.id, status: 'ready', requiresInitialReconcile: false,
              initialReconcile: 'not_required', revision: state.localHydration.revision + 1,
            },
          }));
          globalThis.__o86MemoryVisibleStartedAt = performance.now();
          globalThis.__o86MemoryStages = [];
          let previous = '';
          clearInterval(globalThis.__o86MemoryStageTimer);
          globalThis.__o86MemoryStageTimer = setInterval(() => {
            const map = globalThis.__cairnMap;
            const prepared = stores.usePreparedMemoryCoverageStore?.getState?.() ?? {};
            const friends = stores.useFriendMemoryStore.getState();
            const state = {
              route: stores.getCurrentRoute?.() ?? null,
              map: Boolean(map),
              styleLoaded: Boolean(map?.isStyleLoaded?.()),
              mapLoaded: Boolean(map?.loaded?.()),
              tilesLoaded: Boolean(map?.areTilesLoaded?.()),
              prepared: prepared.status ?? null,
              preparedEvidence: prepared.coverage?.evidenceCount ?? null,
              friendLoading: friends.loading,
              visibleFriends: friends.getVisibleGeometries().length,
              fogSource: Boolean(map?.getSource?.('memory-fog-src')),
              friendSource: Boolean(map?.getSource?.('memory-friend-union-src')),
              overlapSource: Boolean(map?.getSource?.('memory-overlap-src')),
              sourceLoaded: Object.fromEntries(['memory-fog-src', 'memory-friend-union-src', 'memory-overlap-src']
                .map(id => [id, map?.getSource?.(id) ? Boolean(map?.isSourceLoaded?.(id)) : null])),
              rendered: Object.fromEntries(['memory-fog', 'memory-friend-union', 'memory-overlap']
                .map(id => {
                  try { return [id, map?.getLayer?.(id) ? map.queryRenderedFeatures(undefined, { layers: [id] }).length : null]; }
                  catch { return [id, -1]; }
                })),
              veil: Boolean(document.querySelector('[data-testid="memory-entry-veil"]')),
            };
            const serialized = JSON.stringify(state);
            if (serialized !== previous) {
              globalThis.__o86MemoryStages.push({ atMs: performance.now() - globalThis.__o86MemoryVisibleStartedAt, ...state });
              previous = serialized;
            }
          // Stage accounting must not become the workload. Each sample calls
          // queryRenderedFeatures for three GeoJSON layers, so sampling at
          // render cadence competes with the very Mapbox worker/paint path we
          // are measuring. 100 ms still resolves every user-visible stage
          // while keeping diagnostic overhead bounded and declared.
          }, 100);
          stores.navigationRef.reset({ index: 1, routes: [{ name: 'Home' }, { name: 'Memory' }] });
        }, { userValue: user, centerValue: center, scopeValue: scenario.scope });

        const handle = await page.waitForFunction(({ expectFriend, expectOverlap, selectedCount }) => {
          const map = globalThis.__cairnMap;
          if (!map || document.querySelector('[data-testid="memory-entry-veil"]')) return false;
          const fogSource = map.getSource?.('memory-fog-src');
          const fogLayer = map.getLayer?.('memory-fog');
          if (!fogSource || !fogLayer) return false;
          const friendSource = map.getSource?.('memory-friend-union-src');
          const overlapSource = map.getSource?.('memory-overlap-src');
          if (expectFriend && !friendSource) return false;
          if (!expectFriend && friendSource) return false;
          if (expectOverlap && !overlapSource) return false;
          if (!expectOverlap && overlapSource) return false;
          const visibleFriends = globalThis.__cairnStores.useFriendMemoryStore.getState().getVisibleGeometries();
          if (visibleFriends.length !== selectedCount) return false;
          let fogPainted = 0; let friendPainted = 0; let overlapPainted = 0; let basemapPainted = 0;
          try { fogPainted = map.queryRenderedFeatures(undefined, { layers: ['memory-fog'] }).length; } catch {}
          try { friendPainted = expectFriend ? map.queryRenderedFeatures(undefined, { layers: ['memory-friend-union'] }).length : 0; } catch {}
          try { overlapPainted = expectOverlap ? map.queryRenderedFeatures(undefined, { layers: ['memory-overlap'] }).length : 0; } catch {}
          try {
            const baseLayerIds = (map.getStyle?.().layers ?? [])
              .filter(layer => !String(layer.id).startsWith('memory-') && ['fill', 'line', 'symbol'].includes(layer.type))
              .map(layer => layer.id);
            basemapPainted = baseLayerIds.length
              ? map.queryRenderedFeatures(undefined, { layers: baseLayerIds }).length
              : 0;
          } catch {}
          if (basemapPainted < 1 || fogPainted < 1
            || (expectFriend && friendPainted < 1) || (expectOverlap && overlapPainted < 1)) return false;
          const fogData = fogSource._data;
          return {
            visibleAtMs: performance.now() - globalThis.__o86MemoryVisibleStartedAt,
            basemapPainted, fogPainted, friendPainted, overlapPainted,
            visibleFriendSources: visibleFriends.length,
            fogGeometryType: fogData?.geometry?.type ?? null,
            fogGeometryHash: fogData ? JSON.stringify(fogData).length : 0,
          };
        }, {
          expectFriend: scenario.expectFriend,
          expectOverlap: scenario.expectOverlap,
          selectedCount: scenario.selected.length,
        }, { timeout: 15_000, polling: 50 });
        measurement = await handle.jsonValue();
        measurement.stages = await page.evaluate(() => {
          clearInterval(globalThis.__o86MemoryStageTimer);
          return globalThis.__o86MemoryStages ?? [];
        });
        if (trial === 0) await page.screenshot({ path: path.join(outputDir, `${scenario.id}-actual-mapbox-390x844.png`) });
      } catch (error) {
        runtimeErrors.push(error?.stack || String(error));
        measurement = await page.evaluate(() => {
          clearInterval(globalThis.__o86MemoryStageTimer);
          const map = globalThis.__cairnMap;
          const stores = globalThis.__cairnStores;
          return {
            timeout: true,
            stages: globalThis.__o86MemoryStages ?? [],
            final: {
              mapLoaded: Boolean(map?.loaded?.()),
              tilesLoaded: Boolean(map?.areTilesLoaded?.()),
              prepared: stores?.usePreparedMemoryCoverageStore?.getState?.().status ?? null,
              friendStates: stores?.useFriendMemoryStore?.getState?.().sourceStates ?? {},
              visibleFriends: stores?.useFriendMemoryStore?.getState?.().getVisibleGeometries?.().length ?? 0,
              fogSource: Boolean(map?.getSource?.('memory-fog-src')),
              friendSource: Boolean(map?.getSource?.('memory-friend-union-src')),
              overlapSource: Boolean(map?.getSource?.('memory-overlap-src')),
              veil: Boolean(document.querySelector('[data-testid="memory-entry-veil"]')),
            },
          };
        }).catch(() => null);
      }
      results.push({
        scenario: scenario.id,
        trial: trial + 1,
        coldClientGeometryCache: true,
        measurement,
        runtimeErrors,
        clientLogs,
        pass: Boolean(measurement && Number(measurement.visibleAtMs) < 5_000 && runtimeErrors.length === 0),
      });
        await page.close();
      }
    } finally {
      await context.close();
    }
  }
} finally {
  await browser.close();
}

const scenarioSummaries = Object.fromEntries(scenarios.map(scenario => {
  const rows = results.filter(result => result.scenario === scenario.id);
  const timings = rows.flatMap(result => {
    const value = Number(result.measurement?.visibleAtMs);
    return Number.isFinite(value) ? [value] : [];
  });
  return [scenario.id, {
    ...summarize(timings),
    pass_count: rows.filter(result => result.pass).length,
    fail_count: rows.filter(result => !result.pass).length,
    gate: timings.length === trialCount && percentile(timings, 0.95) < 5_000 ? 'PASS' : 'FAIL',
  }];
}));
const report = {
  generated_at: new Date().toISOString(),
  candidate: 'current O86 worktree',
  fixture_provenance: fixture.provenance,
  fixture_sha256: sha(fixture),
  fixture_counts: { viewer_mine: 2_000, dense_friend: 10_000, overlap_friend: 2_000, distinct_friend: 1_000 },
  client_profile: {
    browser: 'Playwright system Chromium/Chrome', viewport: '390x844', trials_per_scenario: trialCount,
    cache: 'fresh page JS realm + unique account + cleared storage per trial; no client geometry/display cache reuse; ordinary Mapbox HTTP resource cache retained within each scenario',
    basemap: 'real hosted Mapbox style/tiles',
    transport: 'captured isolated real-API JSON with recorded healthy p95 delay injected (names 64ms, Mine 140ms, Friends 224/255ms)',
    finish: 'entry/selection to actual production Mapbox sources/layers present, expected source count, queryRenderedFeatures nonzero, and entry veil absent',
    diagnostic_sampling: '100ms correlated stage sampler + 50ms completion probe; each probe still requires real basemap and every expected Mapbox layer to return visible features',
  },
  scenario_summaries: scenarioSummaries,
  results,
  verdict: Object.values(scenarioSummaries).every(summary => summary.gate === 'PASS') ? 'PASS' : 'FAIL',
};
fs.writeFileSync(path.join(outputDir, 'report.json'), `${JSON.stringify(report, null, 2)}\n`);
console.log(JSON.stringify({ outputDir, verdict: report.verdict, scenarioSummaries }, null, 2));
if (report.verdict !== 'PASS') process.exitCode = 1;
